import*as THREE from'three';import{Button,Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
/** S1 is physically behind the closed rear cover, not an exterior switch. */
class InspectionSlide extends Button{get interactive(){return this.meta.assemblyInspection===true;}onPointerDown(info){if(this.interactive)super.onPointerDown(info);}onPointerUp(info){if(this.interactive)super.onPointerUp(info);}onPointerCancel(info){if(this.interactive)super.onPointerCancel(info);}}
function board(host){const s=new THREE.Shape();s.moveTo(-10.4,-12.2);s.lineTo(-8.5,-14.1);s.lineTo(8.5,-14.1);s.lineTo(10.4,-12.2);s.lineTo(10.4,-7.6);s.lineTo(8,-7.6);s.absarc(8,-4,3.6,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.4,-.4);s.lineTo(10.4,12.1);s.lineTo(8.5,14);s.lineTo(-8.5,14);s.lineTo(-10.4,12.1);s.lineTo(-10.4,-.4);s.lineTo(-8,-.4);s.absarc(-8,-4,3.6,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.4,-7.6);s.closePath();const hole=new THREE.Path();hole.absarc(0,-4,2.05,0,Math.PI*2,false);s.holes.push(hole);const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.85,bevelEnabled:false,curveSegments:48}),materials.plastic(0x117636,{roughness:.87}),[0,0,-1.2],'RCA fixed green PCB with genuine mounting reliefs and retaining bore');pcb.userData={role:'physical-pcb',inferred:true};const metal=materials.metal(0xb8bba9,{roughness:.4}),dark=materials.plastic(0x1c211b),parts=[];for(const[x,y,w,h]of[[-6.5,1.3,1.6,3.2],[5.6,1.6,1.5,2.4],[8,1.6,2.5,1.5]]){parts.push(slab(host.body,w,h,.55,.07,[x,y,-.34],dark,[],.015));parts.at(-1).name='RCA fixed passive physical package';for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(w,.32,.58),metal,[x,y+sign*(h/2-.1),-.32],'RCA passive solder termination');}return{pcb,parts};}
function selector(host,inspection){const p=spec.channel.position,metal=materials.metal(0xaeb2a4,{roughness:.45}),dark=materials.plastic(0x171c17),body=slab(host.body,6.4,3.1,1.3,.1,[0,1.6,-.35],dark,[],.02);body.name='RCA S1 fixed internal SPDT body';const cover=slab(host.body,6.7,3.3,.28,.1,[0,1.6,.94],metal,[{w:3.7,h:1.25,r:.09}],.02);cover.name='RCA S1 actual slotted fixed metal cover';for(const x of[-2,0,2])mesh(host.body,new THREE.BoxGeometry(.55,.85,.22),metal,[x,-.3,-.26],'RCA S1 soldered physical terminal');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.8,.45,.4),metal,[sign*3.3,1.6,.2],'RCA S1 fixed case lug');const cap=new THREE.Group();cap.name='RCA S1 black retained channel thumb';mesh(cap,new THREE.BoxGeometry(1.35,.9,.65),dark,[0,0,0],'RCA S1 actual moving thumb');for(const x of[-.4,0,.4])mesh(cap,new THREE.BoxGeometry(.12,.82,.09),materials.plastic(0x343a30),[x,0,.36],'RCA S1 thumb grip');const channel=host.add(new InspectionSlide({id:'channel',label:'S1 internal retained channel slide',position:p,mesh:cap,axis:spec.channel.axis,travel:spec.channel.travelMm,latching:true,meta:{role:'visual-control',assemblyInspection:inspection,mechanism:'retained-slide',positions:spec.channel.positions,sourceLabels:spec.channel.sourceLabels,travelEvidence:spec.channel.travelEvidence,scope:'Actual single internal slide shape/input intent only. Closed shell blocks pointer;covers:false exposes it. External visual position never switches IO,audio,video,signals or electrical circuits.'}}));if(!inspection)channel.cap.traverse(o=>{delete o.userData.component;});return{body,cover,channel};}
function ring(parent,points,p,mat,name){return mesh(parent,new THREE.LatheGeometry(points.map(v=>new THREE.Vector2(...v)),96),mat,p,name);}
function rca(host){const group=new THREE.Group();group.name='RCA actual single female socket with open nested physical bores';host.body.add(group);const gold=materials.metal(0xc6ac3c,{roughness:.26}),steel=materials.metal(0xb7b9a8,{roughness:.34}),yellow=materials.plastic(0xe4ce28,{roughness:.45}),phenolic=materials.plastic(0x45482a,{roughness:.8}),centre=spec.rca.position[2];const barrel=ring(group,[[4.5,11.9],[4.75,12.4],[4.75,20.15],[4.5,20.4],[3.45,20.4],[3.35,20.1],[3.35,12.4],[4.5,11.9]],[0,0,centre],gold,'RCA gold female outer barrel with open FrontSide wall');const insulator=ring(group,[[3.34,14.2],[3.34,19.9],[1.35,19.9],[1.35,14.2],[3.34,14.2]],[0,0,centre],yellow,'RCA recessed yellow annular dielectric with open centre');const contact=ring(group,[[1.32,14.3],[1.32,19.55],[1.12,19.75],[.85,19.75],[.85,14.3],[1.32,14.3]],[0,0,centre],steel,'RCA recessed centre female contact open bore');const backing=mesh(group,new THREE.CylinderGeometry(3.32,3.32,.35,96),phenolic,[0,14.1,centre],'RCA deep physical dielectric base behind female contact');for(const sign of[-1,1]){mesh(group,new THREE.BoxGeometry(.38,5.6,8.1),gold,[sign*5.65,10.2,4.1],'RCA folded gold shield bracket side');mesh(group,new THREE.BoxGeometry(1.1,1.9,.5),gold,[sign*5.65,8.2,-.1],'RCA fixed shield solder foot');}const bracketShape=new THREE.Shape();bracketShape.moveTo(-5.85,-4.75);bracketShape.lineTo(5.85,-4.75);bracketShape.lineTo(5.85,4.65);bracketShape.lineTo(-5.85,4.65);bracketShape.closePath();const bore=new THREE.Path();bore.absarc(0,0,4.25,0,Math.PI*2,false);bracketShape.holes.push(bore);const bracket=mesh(group,new THREE.ExtrudeGeometry(bracketShape,{depth:.35,bevelEnabled:false,curveSegments:64}),gold,[0,12.2,centre],'RCA square shield flange with genuine cylindrical aperture');bracket.rotation.x=-Math.PI/2;const tail=mesh(group,new THREE.BoxGeometry(2.2,6.8,.35),steel,[0,8.6,.75],'RCA real folded centre solder contact');const bend=mesh(group,new THREE.BoxGeometry(2.2,.35,4.65),steel,[0,11.8,3.05],'RCA real centre contact upright behind deep socket');const port=host.add(new Port({id:'rca',label:'Single RCA female · visual attachment only',connector:'rca-female',position:spec.rca.position,quaternion:portQuaternion('top'),hitSize:[9.5,1,9.5],pins:[{n:1,name:'SIG'},{n:2,name:'GND'}],meta:{role:'visual-connector',face:'top',physicalConnector:'rca-female',scope:'Single signal/ground female socket only. No supplied RCA plug/cable,audio,video,stereo channel mixing,waveform or electrical implementation.'}}));return{group,barrel,insulator,contact,backing,bracket,tail,bend,port};}
function grove(host){const g=new THREE.Group();g.name='RCA real open black HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.76}),metal=materials.metal(0xb9b8a5,{roughness:.43}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'RCA Grove '+n),depth=6.3;for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-5.8],`tail ${i+1}`,metal);}const port=host.add(new Port({id:'grove',label:'PORT.B · I/O',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'IN1',color:'yellow'},{n:4,name:'IN2',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment,four contacts and own rear-label pin names only. No electrical IO-name equivalence,voltage,audio,video,GPIO or firmware behavior.'}}));return{group:g,contacts,port};}
export function buildRCA(host,options={}){const inspection=options.covers===false,parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),channel=selector(host,inspection),socket=rca(host),input=grove(host),fixing=screw(host.body,[0,-4,-3.78],'back',1.35);fixing.name='RCA actual recessed fixed hex retaining screw';mesh(host.body,new THREE.CylinderGeometry(.65,.65,6,32).rotateX(Math.PI/2),materials.metal(0xa0a49a),[0,-4,-.7],'RCA concealed fixed retaining screw shank');host.rcaAssembly={parts,pcb,selector:channel,socket,input,fixing,artwork:[]};host.unitStickers=host.rcaAssembly.artwork=addStickers(host);if(inspection){for(const shell of Object.values(parts))shell.visible=false;for(const panel of host.unitStickers)if(Object.values(parts).includes(panel.parent))panel.visible=false;}}
